        vars['email_state'] = 'ok'
        vars['email_addr'] = em
        local, dom = em.split('@', 1)
        if len(local) <= 14 and re.match(r'^[a-z]+([.][a-z]+)?$', local):
            vars['email_spoken'] = em
        else:
            vars['email_spoken'] = local[:1] + ' ile başlayan ' + dom.split('.')[0] + ' adresiniz'
    else:
        vars['email_state'] = 'none'
b = getbody('cards_balance', 'cards_balance')
code = rcode(b) or str(vars.get('cards_balance_code') or '')
d = bdata(b)
sel = json.loads(vars.get('sel_json') or '{}')
if code != '1' or not d:
    vars['route'] = 'error'
else:
    if not sel.get('productName') and d.get('productName'):
        sel['productName'] = d.get('productName')
    if not sel.get('cardNumberLast4'):
        sel['cardNumberLast4'] = d.get('cardNumberLast4')
    vars['sel_name'] = cname(sel)
    vars['sel_l4w'] = l4w(sel.get('cardNumberLast4'))
    vars['stmt_date_raw'] = str(d.get('statementDate') or '')
    t = today()
    stmt = pdate(d.get('statementDate'))
    due = pdate(d.get('lastPayDate'))
    blocks = [('TL', 'debtTL'), ('USD', 'debtUSD'), ('EUR', 'debtEUR'), ('GBP', 'debtGBP')]
    has = dict()
    clear = []
    for cur, key in blocks:
        blk = d.get(key)
        if not isinstance(blk, dict) or not blk:
            continue
        if fnum(blk.get('remainingDebt')) > 0:
            has[cur] = blk
        else:
            clear.append(cur)
    tl = d.get('debtTL') if isinstance(d.get('debtTL'), dict) else dict()
    parts = []
    intro = intro_name(sel) + 'a ait ' + sdate(d.get('statementDate')) + ' tarihinde kesilen ekstre '
    if stmt is None:
        parts.append(intro_name(sel) + 'a ait kesilmiş bir ekstre bulunmadığından borcunuz bulunmamaktadır.')
    elif str(d.get('statementPaymentStatus')) == 'NO_DEBT' or not has:
        parts.append(intro_name(sel) + 'ın ' + sdate(d.get('statementDate')) + ' tarihli ekstresinden borcunuz bulunmamaktadır.')
        if fnum(tl.get('totalDebt')) > 0:
            parts.append('Gelecek dönemler dahil toplam borcunuz ' + money(tl.get('totalDebt'), 'TL') + '.')
        if due is not None:
            parts.append('Son ödeme tarihiniz ' + sdate(d.get('lastPayDate')) + ' olacaktır.')
    else:
        if t is not None and stmt == t:
            parts.append('Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
        moved = [CUR[c][0] for c in ('USD', 'EUR', 'GBP') if isinstance(d.get('debt' + c), dict) and fnum(d.get('debt' + c).get('transferAmount')) > 0]
        if moved:
            parts.append(joinlist(moved) + ' borcunuzun bir kısmı Türk Lirası borcunuza aktarılmıştır.')
        first = True
        if 'TL' in has:
            X = money(tl.get('statementDebt'), 'TL')
            Z = money(tl.get('minPayment'), 'TL')
            Y = money(tl.get('remainingDebt'), 'TL')
            T = money(tl.get('remainingMinPayment'), 'TL')
            rmin = fnum(tl.get('remainingMinPayment'))
            minp = fnum(tl.get('minPayment'))
            if rmin <= 0:
                s = 'Türk Lirası borcunuz ' + X + ', kalan toplam borcunuz ' + Y + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
            elif rmin >= minp:
                s = 'Türk Lirası borcunuz ' + X + ', ödenmesi gereken minimum tutar ' + Z + '.'
            else:
                s = 'Türk Lirası borcunuz ' + X + ', ödenmesi gereken minimum tutar ' + Z + ', kalan toplam borcunuz ' + Y + ', kalan minimum ödeme tutarınız ' + T + '.'
            parts.append(intro + s)
            first = False
        for cur in ('USD', 'EUR', 'GBP'):
            if cur in has:
                blk = has[cur]
                s = CUR[cur][0] + ' borcunuz ' + money(blk.get('statementDebt'), cur) + ', kalan toplam borcunuz ' + money(blk.get('remainingDebt'), cur) + ', ödenmesi gereken minimum tutar ' + money(blk.get('minPayment'), cur) + '.'
                parts.append((intro if first else '') + s)
                first = False
        if clear:
            parts.append(joinlist([CUR[c][0] for c in clear]) + ' borcunuz bulunmamaktadır.')
        passed = t is not None and due is not None and t > due
        if passed and str(d.get('automaticPaymentFlag')) == 'Y' and fnum(tl.get('remainAutomaticPaymentAmount')) > 0:
            parts.append('Otomatik ödeme talimatınızdan alınacak kalan tutar ' + money(tl.get('remainAutomaticPaymentAmount'), 'TL') + '.')
        if t is not None and due is not None and t == due:
            parts.append('Borçlarınız için son ödeme tarihiniz bugündür.')
        elif passed:
            parts.append('Borçlarınız için son ödeme tarihiniz olan ' + sdate(d.get('lastPayDate')) + ' geçmiştir.')
            if fnum(tl.get('totalDebt')) > 0:
                parts.append('Gelecek dönemler dahil toplam Türk Lirası borcunuz ' + money(tl.get('totalDebt'), 'TL') + '.')
        elif due is not None:
            parts.append('Borçlarınız için son ödeme tarihiniz ' + sdate(d.get('lastPayDate')) + suffix(d.get('lastPayDate')) + '.')
    vars['reading_text'] = ' '.join(parts)
    if len(eligible()) > 1:
        vars['menu_stage'] = 'another'
        vars['menu_q'] = 'Başka bir kartınızın borcunu öğrenmek ister misiniz?'
    else:
        vars['menu_stage'] = 'offer'
        vars['menu_q'] = offer_text()
    vars['menu_choice'] = 'none'
    vars['route'] = 'read'
''', [route_t("speak_reading", "route", "read"), always("end_fail_agent")])

