    stmt = pdate(d.get('statementDate'))
    due = pdate(d.get('lastPayDate'))
    blocks = [('TL', 'debtTL'), ('USD', 'debtUSD'), ('EUR', 'debtEUR'), ('GBP', 'debtGBP')]
    has = dict()
    clear = []
    for cur, key in blocks:
        blk = d.get(key)
        if not isinstance(blk, dict) or not blk:
            continue
        if fnum(blk.get('remainingDebt')) > 0:
            has[cur] = blk
        else:
            clear.append(cur)
    tl = d.get('debtTL') if isinstance(d.get('debtTL'), dict) else dict()
    parts = []
    intro = intro_name(sel) + 'a ait ' + sdate(d.get('statementDate')) + ' tarihinde kesilen ekstre '
    if stmt is None:
        parts.append(intro_name(sel) + 'a ait kesilmiş bir ekstre bulunmadığından borcunuz bulunmamaktadır.')
