            parts.append(intro + s)
            first = False
        for cur in ('USD', 'EUR', 'GBP'):
            if cur in has:
                blk = has[cur]
                s = CUR[cur][0] + ' borcunuz ' + money(blk.get('statementDebt'), cur) + ', kalan toplam borcunuz ' + money(blk.get('remainingDebt'), cur) + ', ödenmesi gereken minimum tutar ' + money(blk.get('minPayment'), cur) + '.'
                parts.append((intro if first else '') + s)
                first = False
        if clear:
            parts.append(joinlist([CUR[c][0] for c in clear]) + ' borcunuz bulunmamaktadır.')
        passed = t is not None and due is not None and t > due
        if passed and str(d.get('automaticPaymentFlag')) == 'Y' and fnum(tl.get('remainAutomaticPaymentAmount')) > 0:
