            if fnum(tl.get('totalDebt')) > 0:
                parts.append('Gelecek dönemler dahil toplam Türk Lirası borcunuz ' + money(tl.get('totalDebt'), 'TL') + '.')
        elif due is not None:
            parts.append('Borçlarınız için son ödeme tarihiniz ' + sdate(d.get('lastPayDate')) + suffix(d.get('lastPayDate')) + '.')
    vars['reading_text'] = ' '.join(parts)
    if len(eligible()) > 1:
        vars['menu_stage'] = 'another'
        vars['menu_q'] = 'Başka bir kartınızın borcunu öğrenmek ister misiniz?'
    else:
        vars['menu_stage'] = 'offer'
        vars['menu_q'] = offer_text()
    vars['menu_choice'] = 'none'
    vars['route'] = 'read'
