            found = [c for c in pool if re.sub(r'[^0-9]', '', str(c.get('cardNumber') or '')) == digits]
        mode = 'full'
    elif len(digits) >= 6:
        last6 = digits[-6:]
        found = [c for c in pool if '*' not in str(c.get('cardNumber') or '')[-6:] and str(c.get('cardNumber') or '')[-6:] == last6]
        if not found:
            found = [c for c in pool if str(c.get('cardNumberLast4')) == last6[-4:]]
            if len(found) > 1:
                mode = 'need_full'
        else:
            mode = 'six'
    else:
        found = [c for c in pool if str(c.get('cardNumberLast4')) == digits[-4:]]
        if not found:
            found = [c for c in allc if str(c.get('cardNumberLast4')) == digits[-4:]]
        mode = 'four'
else:
    h = norm(hint)
    for w in ('kartım', 'kartımın', 'kartı', 'kart', 'borcu', 'borcunu', 'olan', 'lütfen'):
        h = ' '.join(x for x in h.split() if x != w)
    exact = [c for c in allc if norm(cname(c)) == h and h]
    if exact:
        found = exact
    else:
        found = [c for c in allc if h and (h in norm(cname(c)))]
        if not found and h:
            hw = [x for x in h.split() if x not in ('yıldız',)]
            if hw:
                found = [c for c in allc if all(x in norm(cname(c)).split() for x in hw)]
    mode = 'name'
tries = int(vars.get('card_tries') or 0)
if mode == 'all':
    tries += 1
    msg = 'Borç bilgisini tek tek kart için verebiliyorum. ' + choose_question()
elif len(found) == 1:
    c = found[0]
    if str(c.get('isMainCard')).lower() == 'false':
        tries += 1
        msg = 'Bu kart için borç bilgisi veremiyorum. Lütfen başka bir kartınızı seçin. ' + examples_text(el)
    else:
        vars['sel_json'] = json.dumps(c, ensure_ascii=False)
        vars['sel_card'] = str(c.get('cardNumber') or '')
        vars['cand_json'] = '[]'
        vars['card_tries'] = 0
        vars['route'] = 'selected'
elif len(found) > 1:
    vars['cand_json'] = json.dumps([c.get('cardNumber') for c in found])
    names = []
    for c in found:
        if cname(c) not in names:
            names.append(cname(c))
    l4s = set(str(c.get('cardNumberLast4')) for c in found)
    if mode == 'name' and len(names) > 1:
        msg = 'Bu isme uyan kartlarınız: ' + joinlist(names, ' ve ') + '. Hangisinin borcunu öğrenmek istersiniz?'
    elif mode == 'name':
        msg = (names[0] or 'Bu') + ' isimli birden fazla kartınız var. Kartınızın son dört hanesini söyler misiniz?'
    elif mode == 'four' and len(l4s) == 1:
        msg = 'Son dört hanesi ' + l4w(list(l4s)[0]) + ' olan birden fazla kartınız var. Kartınızın son altı hanesini söyler misiniz?'
    elif mode in ('six', 'need_full', 'full'):
        msg = 'Son altı hanesi aynı olan birden fazla kartınız var. Kart numaranızı söyler misiniz?'
    else:
        msg = 'Kartınızın son dört hanesini söyler misiniz?'
else:
    tries += 1
    vars['cand_json'] = '[]'
    alln = []
    for c in el:
        if cname(c) and cname(c) not in alln:
            alln.append(cname(c))
    msg = 'Bu bilgiyle eşleşen bir kartınız bulunmuyor. Kartlarınız: ' + joinlist(alln, ' ve ') + '. Hangisinin borcunu öğrenmek istersiniz?'
vars['card_tries'] = tries
if vars.get('route') != 'selected' or msg:
    if tries >= 3:
        vars['route'] = 'tries'
    else:
        vars['choose_q'] = msg
        vars['route'] = 'ask'
''', [route_t("cards_balance", "route", "selected"), route_t("end_tries", "route", "tries"),
