            parts.append('Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
        moved = [CUR[c][0] for c in ('USD', 'EUR', 'GBP') if isinstance(d.get('debt' + c), dict) and fnum(d.get('debt' + c).get('transferAmount')) > 0]
        if moved:
            parts.append(joinlist(moved) + ' borcunuzun bir kısmı Türk Lirası borcunuza aktarılmıştır.')
        first = True
        if 'TL' in has:
            X = money(tl.get('statementDebt'), 'TL')
            Z = money(tl.get('minPayment'), 'TL')
            Y = money(tl.get('remainingDebt'), 'TL')
            T = money(tl.get('remainingMinPayment'), 'TL')
